function validate([word, forbidden]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100000) return 'word needs 1 to 100000 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses lowercase letters only.';
  if (!Array.isArray(forbidden) || forbidden.length < 1 || forbidden.length > 100000) return 'forbidden needs 1 to 100000 strings.';
  if (forbidden.some(f => typeof f !== 'string' || !/^[a-z]{1,10}$/.test(f))) return 'Each forbidden string has 1 to 10 lowercase letters.';
  return null;
}

