function longestValidSubstring(word, forbidden) {
  const banned = new Set(forbidden);
  const maxLength = 10;
  let left = 0;
  let best = 0;
  for (let right = 0; right < word.length; right++) {
    for (let start = right; start >= Math.max(left, right - maxLength + 1); start--) {
      if (banned.has(word.slice(start, right + 1))) {
        left = start + 1;
        break;
      }
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

