function longestValidSubstring(word, forbidden) {
  // Grow every substring from every start and stop once it contains a forbidden string.
  let answer = 0;
  for (let i = 0; i < word.length; i++) {
    for (let j = i; j < word.length; j++) {
      const piece = word.slice(i, j + 1);
      if (forbidden.some(f => piece.includes(f))) break;
      answer = Math.max(answer, piece.length);
    }
  }
  return answer;
}

