function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcd'.slice(0, large ? 4 : 1 + Math.floor(rand() * 3));
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const n = large ? 10000 : 1 + Math.floor(rand() * 12);
  let word = '';
  for (let i = 0; i < n; i++) word += pick();
  const count = large ? 2000 : 1 + Math.floor(rand() * 4);
  const forbidden = [];
  // Half the forbidden strings are cut from word so they really occur; the rest are random.
  for (let i = 0; i < count; i++) {
    const length = large ? 5 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 3);
    if (rand() < 0.5 && length <= n) {
      const start = Math.floor(rand() * (n - length + 1));
      forbidden.push(word.slice(start, start + length));
    } else {
      let piece = '';
      for (let j = 0; j < length; j++) piece += pick();
      forbidden.push(piece);
    }
  }
  return [word, forbidden];
}
